def IsEpsBracket (ε : ℝ) (l u : Ω → ℝ) (r : ℝ≥0∞) (P : Measure Ω) : Prop :=
  IsBracket l u ∧ Measurable l ∧ Measurable u ∧ MemLp l r P ∧ MemLp u r P ∧
    eLpNorm (fun x => u x - l x) r P < ENNReal.ofReal ε

